config.command:
set -eu
umask 077
export LC_ALL=C
base=/workspace/fieldkit
[ -d "$base" ] && [ ! -L "$base" ] || { printf 'Create the fieldkit folder in the sandbox workspace first.\n' >&2; exit 2; }
cd "$base"
need() {
  command -v "$1" >/dev/null 2>&1 || { printf 'Missing command: %s. Install the packages listed in this tool.\n' "$1" >&2; exit 127; }
}
check_file() {
  [ -f "$1" ] && [ ! -L "$1" ] || { printf 'Required regular file missing: %s\n' "$1" >&2; exit 2; }
  bytes=$(wc -c < "$1")
  [ "$bytes" -gt 0 ] && [ "$bytes" -le "$2" ] || { printf 'Input is empty or exceeds this tool size limit.\n' >&2; exit 2; }
}
need jq
check_file events.json 2097152
jq -M -s 'if length != 1 then error("Expected one JSON document") else .[0] | if type != "array" then error("Expected an event array") elif length > 2000 then error("Too many events") elif any(.[]; type != "object" or (.timestamp | type) != "string" or (.source | type) != "string" or (.text | type) != "string") then error("Each event needs timestamp, source and text strings") elif any(.[]; .timestamp as $t | (try ($t | fromdateiso8601 | todateiso8601) catch "") != $t) then error("Use valid YYYY-MM-DDTHH:MM:SSZ UTC timestamps") else {events: length, first: (map(.timestamp) | min), last: (map(.timestamp) | max), sources: (group_by(.source) | map({source: .[0].source, events: length}))} end end' ./events.json
